DO $rebase_companion$ BEGIN IF EXISTS (SELECT 1 FROM pg_policies p WHERE p.schemaname = 'public' AND p.tablename = 'track' AND p.policyname = 'track_default_admin_write_delete_ar_6126d9c9' AND NOT (p.cmd = 'DELETE' AND p.permissive = 'PERMISSIVE' AND p.roles = ARRAY['rebase_admin_request']::name[] AND COALESCE(p.qual, 'true') = 'true' AND COALESCE(p.with_check, 'true') = 'true')) THEN EXECUTE 'DROP POLICY "track_default_admin_write_delete_ar_6126d9c9" ON "public"."track"'; END IF; END $rebase_companion$;
DROP POLICY IF EXISTS "track_default_admin_write_delete" ON "public"."track";
CREATE POLICY "track_default_admin_write_delete" ON "public"."track" AS PERMISSIVE FOR DELETE TO "rebase_admin" USING ((SELECT (rebase.uid() IS NULL) OR (string_to_array(rebase.roles(), ',') && ARRAY['admin'])));

